/* iTranslator Text Area | generated by npm run build */
function createTransliterator(config, target = config.defaultTarget) {
  const targetConfig = config.targets[target];
  if (!targetConfig) throw new Error(`Unsupported target: ${target}`);
  if (target === 'sanskrit-iast') {
    const tokens = config.iastTokens || {};
    const keys = Object.keys(tokens).sort((a, b) => b.length - a.length);
    return (input) => {
      let output = '', index = 0;
      while (index < input.length) {
        const key = keys.find(candidate => input.startsWith(candidate, index));
        if (!key) { output += input[index]; index += 1; continue; }
        output += tokens[key]; index += key.length;
      }
      return output;
    };
  }
  const tokens = { ...config.tokens, ...config.aliases, ...config.punctuation };
  const keys = Object.keys(tokens).sort((a, b) => b.length - a.length);
  const consonants = new Set(['k','kh','g','gh','~N','ch','Ch','j','jh','~n','T','Th','D','Dh','N','t','th','d','dh','n','p','ph','b','bh','m','y','r','l','v','w','sh','Sh','S','s','h','L']);
  const vowelMarks = { a: '', A: 'ा', aa: 'ा', i: 'ि', I: 'ी', ii: 'ी', ee: 'ी', u: 'ु', U: 'ू', uu: 'ू', e: 'े', ai: 'ै', o: 'ो', au: 'ौ', RRi: 'ृ', 'R^i': 'ृ', RRI: 'ॄ', 'R^I': 'ॄ', LLi: 'ॢ', 'L^i': 'ॢ', LLI: 'ॣ', 'L^I': 'ॣ', ...(config.vowelMarks || {}) };
  const independentVowels = new Set(Object.keys(vowelMarks));

  const devanagari = (input) => {
    let output = '', index = 0, pendingConsonant = false;
    while (index < input.length) {
      const key = keys.find(candidate => input.startsWith(candidate, index));
        if (!key) {
          if (pendingConsonant) output += '्';
          output += input[index]; pendingConsonant = false; index += 1; continue;
        }
      const glyph = tokens[key];
      if (independentVowels.has(key) && pendingConsonant) output += vowelMarks[key];
      else { if (pendingConsonant && !independentVowels.has(key) && key !== '.N') output += '्'; output += glyph; }
      pendingConsonant = consonants.has(key);
      if (key === '.h' || key === 'M' || key === 'H' || key === '.N') pendingConsonant = false;
      index += key.length;
    }
    return pendingConsonant ? output + '्' : output;
  };
  if (targetConfig.transform === 'script-offset') {
    return (input) => [...devanagari(input)].map(char => {
      if (targetConfig.replacements?.[char]) return targetConfig.replacements[char];
      const code = char.codePointAt(0);
      return code >= 0x0900 && code <= 0x097f && code !== 0x0964 && code !== 0x0965
        ? String.fromCodePoint(code + targetConfig.offset) : char;
    }).join('');
  }
  if (targetConfig.transform === 'tamil') {
    const tamil = {
      'अ':'அ','आ':'ஆ','इ':'இ','ई':'ஈ','उ':'உ','ऊ':'ஊ','ऋ':'஋','ॠ':'௠','ऌ':'஌','ॡ':'௡','ए':'ஏ','ऐ':'ஐ','ओ':'ஓ','औ':'ஔ',
      'ा':'ா','ि':'ி','ी':'ீ','ु':'ு','ू':'ூ','ृ':'்ரு','ॄ':'்ரூ','ॢ':'்லு','ॣ':'்லூ','े':'ே','ै':'ை','ो':'ோ','ौ':'ௌ',
      'क':'க','ख':'க','ग':'க','घ':'க','ङ':'ங','च':'ச','छ':'ச','ज':'ஜ','झ':'ஜ','ञ':'ஞ','ट':'ட','ठ':'ட','ड':'ட','ढ':'ட','ण':'ண','त':'த','थ':'த','द':'த','ध':'த','न':'ந','प':'ப','फ':'ப','ब':'ப','भ':'ப','म':'ம','य':'ய','र':'ர','ल':'ல','व':'வ','ळ':'ள','श':'ஶ','ष':'ஷ','स':'ஸ','ह':'ஹ',
      'ं':'ம்','ः':'ஃ','ँ':'ம்','्':'்','ऽ':'ऽ','।':'।','॥':'॥','ॐ':'ௐ',
      '०':'௦','१':'௧','२':'௨','३':'௩','४':'௪','५':'௫','६':'௬','७':'௭','८':'௮','९':'௯'
    };
    return (input) => [...devanagari(input)].map(char => tamil[char] ?? char).join('');
  }
  return devanagari;
}

let pageConfig;
let pageTarget;
let pageFont;
const settingsIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.43 12.98c.04-.32.07-.65.07-.98s-.02-.66-.07-.98l2.11-1.65a.5.5 0 0 0 .12-.64l-2-3.46a.5.5 0 0 0-.61-.22l-2.49 1a7.36 7.36 0 0 0-1.69-.98L14.5 2.42A.49.49 0 0 0 14 2h-4a.49.49 0 0 0-.49.42l-.38 2.65c-.61.25-1.18.59-1.69.98l-2.49-1a.49.49 0 0 0-.61.22l-2 3.46a.5.5 0 0 0 .12.64l2.11 1.65c-.04.32-.08.65-.08.98s.03.66.08.98l-2.11 1.65a.5.5 0 0 0-.12.64l2 3.46c.12.22.38.31.61.22l2.49-1c.51.4 1.08.73 1.69.98l.38 2.65c.04.24.24.42.49.42h4c.25 0 .46-.18.49-.42l.38-2.65c.61-.25 1.18-.58 1.69-.98l2.49 1c.23.09.49 0 .61-.22l2-3.46a.5.5 0 0 0-.12-.64l-2.11-1.65ZM12 15.5A3.5 3.5 0 1 1 12 8a3.5 3.5 0 0 1 0 7.5Z"/></svg>';
const copyIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1Zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2Zm0 16H8V7h11v14Z"/></svg>';
function configureITranslator(config) {
  pageConfig = config;
  pageTarget = config.defaultTarget;
  pageFont = config.fonts?.default || 'system';
}
function setITranslatorTarget(target) {
  if (!pageConfig?.targets[target]) throw new Error(`Unsupported target: ${target}`);
  pageTarget = target;
  document.querySelectorAll('i-translator-textarea').forEach(widget => {
    widget.flushBuffer();
    const select = widget.querySelector('[data-target-select]');
    if (select) select.value = target;
    widget.updateModeIndicator();
  });
}

function setITranslatorFont(font) {
  if (!pageConfig?.fonts?.options?.[font]) throw new Error(`Unsupported font: ${font}`);
  pageFont = font;
  document.querySelectorAll('i-translator-textarea').forEach(widget => {
    const select = widget.querySelector('[data-font-select]');
    if (select) select.value = font;
    widget.applyFont();
  });
}

function indicator() {
  let element = document.querySelector('#itarea-mode-indicator');
  if (!element) {
    element = document.createElement('div');
    element.id = 'itarea-mode-indicator';
    element.hidden = true;
    document.body.append(element);
  }
  return element;
}

class ITranslatorTextarea extends HTMLElement {
  connectedCallback() {
    if (!pageConfig) throw new Error('Call configureITranslator(config) before adding i-translator-textarea elements.');
    const label = this.getAttribute('label') || 'Text';
    const targets = Object.entries(pageConfig.targets)
      .filter(([id]) => id !== 'sanskrit-iast')
      .map(([id, target]) => `<option value="${id}">${target.label}</option>`).join('');
    const fonts = Object.entries(pageConfig.fonts?.options || { system: { label: 'System default' } })
      .map(([id, font]) => `<option value="${id}">${font.label}</option>`).join('');
    this.innerHTML = `<section class="itarea"><label>${label}</label><div class="itarea__bar"><button type="button" data-mode="itrans" class="active">iTrans</button><button type="button" data-mode="roman">Roman (IAST)</button><button type="button" data-mode="english">English</button></div><div class="itarea__editor"><textarea spellcheck="false" aria-label="${label}" placeholder="Type Sanskrit with ITRANS"></textarea><div class="itarea__actions"><button type="button" class="itarea__icon" data-settings title="Target language settings" aria-label="Target language settings">${settingsIcon}</button><button type="button" class="itarea__icon" data-copy title="Copy text" aria-label="Copy text">${copyIcon}</button></div><div class="itarea__settings" hidden><label>Target language <select data-target-select>${targets}</select></label><label>Font <select data-font-select>${fonts}</select></label></div></div></section>`;
    this.mode = 'itrans';
    this.rawBuffer = '';
    this.bufferStart = null;
    this.input = this.querySelector('textarea');
    this.querySelector('[data-target-select]').value = pageTarget;
    this.querySelector('[data-font-select]').value = pageFont;
    this.applyFont();
    this.setMode('itrans');
    this.querySelector('.itarea__bar').addEventListener('click', event => {
      const button = event.target.closest('button');
      if (button) this.setMode(button.dataset.mode);
    });
    this.querySelector('[data-settings]').addEventListener('click', () => {
      const panel = this.querySelector('.itarea__settings'); panel.hidden = !panel.hidden;
    });
    this.querySelector('[data-target-select]').addEventListener('change', event => setITranslatorTarget(event.target.value));
    this.querySelector('[data-font-select]').addEventListener('change', event => setITranslatorFont(event.target.value));
    this.querySelector('[data-copy]').addEventListener('click', async () => {
      this.flushBuffer();
      await navigator.clipboard.writeText(this.input.value);
      const button = this.querySelector('[data-copy]'); const original = button.innerHTML;
      button.textContent = '✓'; setTimeout(() => { button.innerHTML = original; }, 1200);
    });
    this.input.addEventListener('keydown', event => this.handleKeydown(event));
    this.input.addEventListener('paste', event => this.handlePaste(event));
    this.input.addEventListener('blur', () => this.flushBuffer());
  }

  get transliterate() { return createTransliterator(pageConfig, this.mode === 'roman' ? 'sanskrit-iast' : pageTarget); }

  applyFont() {
    const family = pageConfig.fonts?.options?.[pageFont]?.family || 'system-ui';
    const cssFamily = family === 'system-ui' ? 'system-ui' : `"${family}"`;
    this.style.setProperty('--itarea-font-family', `${cssFamily}, system-ui, sans-serif`);
  }

  updateModeIndicator() {
    const element = indicator();
    element.textContent = this.mode === 'english'
      ? 'No transliteration'
      : this.mode === 'roman'
        ? 'Roman'
        : pageConfig.targets[pageTarget].label;
    element.hidden = false;
  }

  setMode(mode) {
    this.flushBuffer();
    this.mode = mode;
    this.querySelectorAll('button').forEach(button => button.classList.toggle('active', button.dataset.mode === mode));
    this.input.classList.toggle('itarea__english', mode === 'english');
    this.input.classList.toggle('itarea__roman', mode === 'roman');
    this.input.placeholder = mode === 'english' ? 'Type English' : 'Type Sanskrit with ITRANS';
    this.updateModeIndicator();
    this.input.focus();
  }

  handleKeydown(event) {
    if (event.ctrlKey && ['s', 'i'].includes(event.key.toLowerCase())) {
      event.preventDefault(); this.setMode('itrans'); return;
    }
    if ((event.ctrlKey && ['e', 'o'].includes(event.key.toLowerCase())) || event.key === 'Escape') {
      event.preventDefault(); this.setMode('english'); return;
    }
    if (event.ctrlKey && event.key.toLowerCase() === 'r') {
      event.preventDefault(); this.setMode('roman'); return;
    }
    if (this.mode !== 'itrans') return;
    if (event.key === 'Backspace' && this.rawBuffer) {
      event.preventDefault(); this.rawBuffer = this.rawBuffer.slice(0, -1); this.replaceBuffer(); return;
    }
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'Delete'].includes(event.key)) {
      this.flushBuffer(); return;
    }
    if (event.key.length === 1 && !event.metaKey && !event.altKey) {
      event.preventDefault();
      if (this.bufferStart === null) this.bufferStart = this.input.selectionStart;
      this.rawBuffer += event.key;
      this.replaceBuffer();
    } else if (event.key === 'Enter' || event.key === 'Tab') {
      this.flushBuffer();
    }
  }

  handlePaste(event) {
    if (this.mode !== 'itrans') return;
    const text = event.clipboardData?.getData('text/plain');
    if (text === undefined) return;
    event.preventDefault();
    this.flushBuffer();
    const start = this.input.selectionStart;
    this.input.setRangeText(this.transliterate(text), start, this.input.selectionEnd, 'end');
  }

  replaceBuffer() {
    const rendered = this.transliterate(this.rawBuffer);
    const end = this.input.selectionEnd;
    this.input.setRangeText(rendered, this.bufferStart, end, 'end');
  }

  flushBuffer() {
    this.rawBuffer = '';
    this.bufferStart = null;
  }

  get value() { this.flushBuffer(); return this.input.value; }
}

customElements.define('i-translator-textarea', ITranslatorTextarea);

export { configureITranslator, setITranslatorTarget, setITranslatorFont, ITranslatorTextarea };
